define(["editor_tiny/loader","editor_tiny/utils","tiny_zoomclassroom/common","tiny_zoomclassroom/options","tiny_zoomclassroom/commands","tiny_zoomclassroom/configuration"],function(Loader,Utils,Common,Options,Commands,Configuration){return new Promise(async resolve=>{const[tinyMCE,pluginMetadata,setupCommands]=await Promise.all([Loader.getTinyMCE(),Utils.getPluginMetadata(Common.component,Common.pluginName),Commands.getSetup()]);tinyMCE.PluginManager.add(Common.pluginName,editor=>{Options.register(editor);setupCommands(editor);return pluginMetadata;});resolve([Common.pluginName,Configuration]);});});
